import React, { useState } from "react";
import "./Home.css"
import logo from "./logo.png"
import { useEffect } from "react";
import { WiHumidity } from "react-icons/wi";
import { FaWind } from "react-icons/fa";
import { MdOutlineVisibility } from "react-icons/md";
import { TbUvIndex } from "react-icons/tb";
function Home(){
    const [weatherData,setweatherData]=useState("")
    const [city,setcity]=useState("")
    const [inp ,setinp] =useState("")
function handleChange(e){
    setinp(e.target.value)

    

}

async function Weather(city) {
        
      try{
        let res = await fetch(`https://wttr.in/${city}?format=j1`);
        let data = await res.json();
        setweatherData(data)
      }
      catch{
    console.log("nhi hua")
      }
      
    }
    useEffect(()=>{
    let timer = setInterval(()=>{
        if(city)
      Weather(city)
      },1000)
    return ()=>clearInterval(timer)
    },[city])
let humidity =weatherData.current_condition?.[0].humidity

let uvText = "";
let uvIndex =weatherData.current_condition?.[0]?.uvIndex;

if (uvIndex <= 2) {
    uvText = "Low";
}
else if (uvIndex <= 5) {
    uvText = "Moderate";
}
else if (uvIndex <= 7) {
    uvText = "High";
}
else if (uvIndex <= 10) {
    uvText = "Very High";
}
else {
    uvText = "Extreme";
}



    return(
        <div>
         <div className="start_wrap">
<div className="start_ctn" >
    <div className="home_head" >
<img className="home_logo" src={logo} />

<h1 className='home_weather' >Weather</h1>
<h1 className='home_forcasts' >Forecasts</h1>


    </div>
   

    <div className="search_area">
<input  onChange={handleChange} value={inp} placeholder="Enter City Name" type="text" />
<button className="search_btn" onClick={()=>{setcity(inp)}} >Search</button>
    </div>

    <div className="body_area">
<div>
        <h2>{weatherData.nearest_area?.[0].region?.[0].value} - {weatherData.nearest_area?.[0].country?.[0]?.value}</h2>

        <div>
            <h1>{ weatherData.current_condition?.[0]?.temp_C}°C</h1>
        </div>
        <h2>{weatherData.current_condition?.[0].weatherDesc?.[0]?.value}</h2>
        <h3>Feels like {weatherData.current_condition?.[0]?.FeelsLikeC}°C</h3>
        
</div>


        
    </div>

    <div className="body_footer">
<div className="body_footer_wrap">
<div>
    
    <h5>Humidity</h5>
    <WiHumidity /> 
    <h2>{humidity} %</h2> 
   
    
</div>
<div>
    
    <h5>Wind Speed</h5>
    <FaWind /> 
    <h2>{weatherData.current_condition?.[0]?.windspeedKmph} Kmph</h2> 
   
    
</div>

</div>
<div className="body_footer_wrap">
<div>
    
    <h5>Visibility</h5>
    <MdOutlineVisibility />
    <h2>{weatherData.current_condition?.[0]?.visibility} km</h2> 
   
    
</div>
<div>
    
    <h5>UV Index</h5>
    <TbUvIndex/> 
    <h2>{weatherData.current_condition?.[0]?.uvIndex} {uvText}</h2> 
   
    
</div>

</div>

    </div>


</div>
</div>

</div>
            
    
    )
}

export default Home ;